SELECT id, source_log_id AS sourceLogId, host_id AS hostId, event_id AS eventId, event_time AS eventTime, operator_username AS operatorUsername, target_username AS targetUsername, action_type AS actionType, details, create_time AS createTime FROM account_change_logs WHERE host_id = #{hostId} AND target_username = #{targetUsername} AND action_type IN
#{it}
AND event_time >= #{since} AND event_time <= #{until} ORDER BY event_time DESC

